import itertools

N = 4
points = [(r, c) for r in range(1, N + 1) for c in range(1, N + 1)]

def is_adjacent(p1, p2):
    """Checks if two points are adjacent (Chebyshev distance <= 1)."""
    r1, c1 = p1
    r2, c2 = p2
    return max(abs(r1 - r2), abs(c1 - c2)) <= 1

# Calculate |IS_2| (Verification)
k2_total = 0
for p1, p2 in itertools.combinations(points, 2):
    if not is_adjacent(p1, p2):
        k2_total += 1

# Calculate |IS_3|
k3_count = 0
for combo in itertools.combinations(points, 3):
    p1, p2, p3 = combo
    if not is_adjacent(p1, p2) and not is_adjacent(p1, p3) and not is_adjacent(p2, p3):
        k3_count += 1

print(f"Count of IS of size 2 (|IS_2|): {k2_total}")
print(f"Count of IS of size 3 (|IS_3|): {k3_count}")

# Determine k_max by searching for largest IS
def find_max_is_size(points, adjacency_func):
    max_size = 0
    for k in range(1, len(points) + 1):
        found_k = False
        for combo in itertools.combinations(points, k):
            is_valid = True
            for i in range(k):
                for j in range(i + 1, k):
                    if adjacency_func(combo[i], combo[j]):
                        is_valid = False
                        break
                if not is_valid:
                    break
            if is_valid:
                max_size = k
                found_k = True
        if not found_k:
            break
    return max_size

max_k = find_max_is_size(points, is_adjacent)
print(f"Maximum independent set size (k_max): {max_k}")

import itertools

N = 4
points = [(r, c) for r in range(1, N + 1) for c in range(1, N + 1)]

def is_adjacent(p1, p2):
    """Checks if two points are adjacent (Chebyshev distance <= 1)."""
    r1, c1 = p1
    r2, c2 = p2
    return max(abs(r1 - r2), abs(c1 - c2)) <= 1

# Calculate and store all independent set sizes
is_counts = {}
k_max = 0

for k in range(1, len(points) + 1):
    count_k = 0
    for combo in itertools.combinations(points, k):
        is_valid = True
        for i in range(k):
            for j in range(i + 1, k):
                if is_adjacent(combo[i], combo[j]):
                    is_valid = False
                    break
            if not is_valid:
                break
        if is_valid:
            count_k += 1

    is_counts[k] = count_k
    if count_k > 0:
        k_max = k

print(f"Counts of IS sizes: {is_counts}")

# Calculate S = sum(|IS_k|) for k >= 2
S = sum(is_counts[k] for k in is_counts if k >= 2)
print(f"Total configurations S (k >= 2): {S}")
